scr.script:
			var PLAINMESSAGE = 1;
	var ERRORMESSAGE = 0;
	var WARNINGMESSAGE = 2;
	var QUESTIONMESSAGE = 3;
	var tabanz = 0
	var colanz = 0
	var colmapanz = 0
	var tabmapanz = 0
	var lasttabmapping = ""
	var lineanz = 0
	var logicalModel
	var relModel
	var writtenCols={}
	var exportDirec="/Users/stb/Documents/DataModeler/Import"

	function fullmessage(msg,type) {
		Java.type("javax.swing.JOptionPane").showMessageDialog(null
		, msg,'ODM-Translation', type);
	}

	function error(msg) {
		fullmessage(msg,ERRORMESSAGE);
		}
	function message(msg) {
		fullmessage(msg,PLAINMESSAGE);
		}
function trimapo(s){
	return s.replace(/^"|"$/g, '');
}

function curDateStr(){
		var currentdate = new Date();
		return  currentdate.getDate() 
		+ "/" + (currentdate.getMonth()+1) 
		+ "/" + currentdate.getFullYear() + "  " 
		+ currentdate.getHours() + ":" 
		+ currentdate.getMinutes() + ":" + currentdate.getSeconds();
}

function do1line(rmodelname,values){
	//message('do1line |'+rmodelname+'| '+values);
	var rmodel = model.getDesign().getRelationalDesigns().getByName(rmodelname);
	if (rmodel == null){
		throw new Error("\nRelational model '"+rmodelname+"' does not exist.\n");
	} else {modelMapping = rmodel.getRMExtendedMap().getContainerMappings().toArray();
	}
	entiName = values[0];
	attrName = values[1];
	tabName = values[2];
	colName = values[3];
	typeName = values[4];
	//message(entiName+' | '+attrName+' | '+tabName+' | '+colName+' | '+typeName)
	entity = logicalModel.getEntitySet().getByName(entiName);
	if (entity != null) {
		attribute=entity.getElementByName(attrName);
		//if (attribute = null){
			//entity.createAttribute(attrName)
			//attribute = entity.getElementByName(attrName);
			//attribute.setComment("Created on "+curDateStr() +" during import from "+imppath)		
		//}
	}
	table = rmodel.getTableSet().getByName(tabName);	
	// Neue Tabellen werden erzeugt
	if ((table == null) && (tabName != "")) {
		rmodel.createTable(tabName);
		table = rmodel.getTableSet().getByName(tabName);	
		table.setComment("Created on "+curDateStr() +" during import from "+imppath)
		tabanz++
	}
	if (table != null){
		column=table.getElementByName(colName);
	} else  {column = null
	}
	// neue Columns werden erzeugt
	if ((column == null) && (colName != "")){
		//message('neue Column')
		table.createColumn(colName)
		column=table.getElementByName(colName);
		column.setComment("Created on "+curDateStr() +" during import from "+imppath)		
		colanz++
	}	
	if ((entity != null) && (table != null)){
		//muss das exakte Mapping Table-Entity finden, da es mehrere haben kann
		//maps = getTabMap(modelMapping,tab.getObjectID())
		//if (maps.length==0) {
		     mapped = entity.getMappingFor(table)
			if (mapped == null) {
				rmodel.getRMExtendedMap().createMapping(entity,table);
				tabmapanz++
			}
		//}
     	if ((attribute != null) && (column != null)){
     		mapped = column.getMappingFor(entity)
     		if (mapped == null) {
     			rmodel.getRMExtendedMap().createMapping(attribute,column);		
				colmapanz++
     		}
     	}
	}
}
function importFile(fpath){
	var Paths = Java.type('java.nio.file.Paths');
	var Files = Java.type('java.nio.file.Files');
	var lines = Files.readAllLines(Paths.get(fpath)
	             , Java.type('java.nio.charset.StandardCharsets').UTF_8);
	for (lnoif=0;lnoif<lines.length;lnoif++)
 	{	line=lines[lnoif]
 		values= line.split(";");
 		for (iif=0;iif<values.length;iif++)
 			{values[iif]=trimapo(values[iif]);
 			}
 		if (lnoif==0){
 			relModel=values[0];
 			// falls 1. Zeichen von Excel stammt, schneide es ab
 			 if (relModel.match(/^[^A-Za-z]/)) relModel = relModel.substring(1)
 			//message(lnoif+': '+"RelModel= |"+relModel+"|");
 		} else 
 		if (lnoif==1){
 			// skip headers
 			//message(lnoif+': '+"headers= "+values);
 		} else {
	 		//message(lnoif+': '+values);
 			do1line(relModel,values);
 			lineanz++
 		} 		
 	};
}
function importMapping() {
	var impdirec="~/Documents/DataModeler/Import";
	//Create a file chooser
	var Filebrowse = Java.type("javax.swing.JFileChooser");
	f = new Filebrowse('/Users/stb/Documents/DataModeler/Import');
	returnVal= f.showOpenDialog(null);
	if (returnVal == Filebrowse.APPROVE_OPTION) {
		imppath= f.getSelectedFile();
		//message(imppath);
	}
	tabanz = 0
	colanz = 0
	colmapanz = 0
	lineanz = 0
	logicalModel = model.getDesign().getLogicalDesign();
	importFile(imppath);
	message("Parsed "+lineanz+" lines from file "+imppath+".\n"
			+"Created "+tabanz+" tables, "+colanz+" columns,\n"
			+ "Mapped "+tabmapanz+" tables to entities and " +colmapanz+" columns to attributes") // +tabmapanz+" table- and " 

}
function chooseModel(rmodel){
	var rmodels = model.getDesign().getRelationalDesigns().toArray();
	if (rmodels.length == 0) throw new Error("\n***MAPPING: no relational models available ***\n");
	if (rmodels.length == 1) {
		antwort = rmodels[0]
	} else {
		if (rmodel == null) rmodel = rmodels[0]
		antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null, 
        	"Choose relational model",
			"choose model",
			QUESTIONMESSAGE,
			null, 
			rmodels,rmodel);
	}
	return antwort
}
function nvl(x){return x==null ? "" : x }

function getColMap(colID,cmap){
	colsmap=[]
	if (cmap == null) return colsmap
	for (icolmap=0;icolmap<cmap.length;icolmap++){
		//message(colID+'|'+cmap[icolmap].getRelID())
		if (colID == cmap[icolmap].getRelID()) colsmap.push(cmap[icolmap])
	}
	return colsmap
}
function writeMapLine(fw,tab,enti,col,attr){
	//message('write'+tab+enti+col+attr)
	fw.write(nvl(enti)+';'+nvl(attr)+';'+tab+';'+nvl(col)+';\n')
}
function printColsMap(fw,tab,lastOne,enti,cmap){
	cols=tab.getElementsCollection().toArray()
	//message(tab+'|'+enti+'|'+cols.length+'|'+cmap.length)
	if (enti!=null) writeMapLine(fw,tab,enti,null,null)
	//cols.sort()
	for (icpcm=0;icpcm<cols.length;icpcm++){
		col = cols[icpcm]
		colkey = tab+'.'+col
		colmaps=getColMap(col.getObjectID(),cmap)
		if (colmaps.length==0) {
			//nicht gemappte Columns werden nur 1x geschrieben.
			if (lastOne && !(colkey in writtenCols)) writeMapLine(fw,tab,null,col,null)
		}else{
			if (enti != null) {
				for (impcm=0;impcm<colmaps.length;impcm++){
					attrName=enti.getElementByID(colmaps[impcm].getLogID())
					//message('vor dem Schreiben='+colmaps[impcm].getLogID()+'|'+col+'|'+attrName)
					writeMapLine(fw,tab,enti,col, attrName)
					writtenCols[colkey]=true
				}
			}
		}
	}
}
function getTabMap(modelMapping,tabID){
	maps=[]
	for (imtm=0;imtm<modelMapping.length;imtm++){
		if (tabID == modelMapping[imtm].getRelID()) maps.push(modelMapping[imtm])
	}
	return maps
}
function printCols(modelMapping,fw,tab){
	maps = getTabMap(modelMapping,tab.getObjectID())
	if (maps.length==0) {
		printColsMap(fw,tab,null,null)
	} else {
		for (impc=0;impc<maps.length;impc++){
			enti=logicalModel.getEntitySet().getObjectByID(maps[impc].getLogID())
			//message(enti+':'+maps[im].getLogType()+':'+maps[impc].getRelType())
			cmap=maps[impc].getContainedMappings().toArray()
			printColsMap(fw,tab,(impc==maps.length-1),enti,cmap)
		}
	}
}

function printCVS (modelMapping,fw){
	entiType = 0
	colType = 1
	tableType = 4
	attrType = 5
	fw.write(relModel+';;;;\n')
	fw.write('entityName;attrName;tableName;columnName;dataType\n')
	tables = relModel.getTableSet().toArray();
	for (itpc=0;itpc<tables.length;itpc++){
		printCols(modelMapping,fw,tables[itpc])
	}
}
function chooseFile(direc,fileName){
	//Create a file chooser
	var Filebrowse = Java.type("javax.swing.JFileChooser");
	var File = Java.type("java.io.File");
	f = new Filebrowse(direc);
	f.setSelectedFile(new File(fileName));
	returnVal= f.showSaveDialog(null);
	if (returnVal == Filebrowse.APPROVE_OPTION) {
		return  f.getSelectedFile();
	} else {
		return null
	}
}
function createFile(fileName){
	//Create a file chooser
	var FileWriter=Java.type('java.io.FileWriter')
	fw = new FileWriter(fileName);    
	return fw
}

function headers(rmodels,nurX){
	retval = ''
	for (ih=0;ih<rmodels.length;ih++){
		retval += ';'+rmodels[ih]
		// extra header for table | attribute entries
		if (! nurX) { retval += ';'}
	}
	return retval
}

function getColName(rmod,tabID,colID){
	tab=rmod.getTableSet().getObjectByID(tabID)
	col = tab.getElementByID(colID)
	return tab+'.'+col
}

function	getMappings(rmodels){
	lmappings = {}
	if (rmodels == null) return lmappings
	for (imod=0;imod<rmodels.length;imod++){
		rmod=rmodels[imod]
		lmappings[rmod.getName()]={}
		//message(lmappings[rmod.getName()]['123:123'])
		modelMap= rmod.getRMExtendedMap().getContainerMappings().toArray();
		//message("modelMapAnz="+modelMap.length)
		if (modelMap != null) {
			for (imgm=0;imgm<modelMap.length;imgm++){
				entiID = modelMap[imgm].getLogID()
				// Attributmappings
				cmap=modelMap[imgm].getContainedMappings().toArray()
				if (cmap != null) {
					for (icgm=0;icgm<cmap.length;icgm++){
						//message("modelmap RELID="+cmap[imgm].getRelID()+"\nName="+cmap[icgm])};
						//rmod.getElementByID(modelMap[imgm].getRelID()))
						attrID = cmap[icgm].getLogID()
						key = entiID+'.'+attrID
						lmappings[rmod.getName()][key]=
						   getColName(rmod,modelMap[imgm].getRelID()
						            ,cmap[icgm].getRelID()) 
					}
				}
			}
		}
	}
	//message('vorReturn'+lmappings['Relational_1'])
	return lmappings
}

function logicalElement(mappings,rmodels,logElem,nurX){	
	elemID = logElem.getObjectID()
	//message(enti)
	if (logElem.getObjectTypeName() == 'Entity'){
		attrs=logElem.getElementsCollection().toArray()
	} else {// assume Relationship
		attrs=logElem.getAttributesCollection().toArray()	
		if (! logElem.isManyToMany()) {
			// Relationships 1:1 and m:1 can become columns
			srcCard = logElem.getSourceCardinalityString()
			targCard = logElem.getTargetCardinalityString()
			srcOpt = logElem.isOptionalSource()
			targOpt = logElem.isOptionalTarget()
			//message(logElem.getName()+':'+srcCrd+':'+targCard+':'+srcOpt+':'+targOpt)
			line= '"'+logElem.getName()+'";;'
			line+='\n'
			fw.write(line)
		}
	}
	//message(logElem.getName()+'  '+attrs.length)
	if (attrs != null){
		for (iattrac=0;iattrac<attrs.length;iattrac++){
			attr=attrs[iattrac]
			attrID = attr.getObjectID()
			key=elemID+'.'+attrID

			line= logElem.getName()+';'+attr
			for (irmpm=0;irmpm<rmodels.length;irmpm++){
				mapentry = mappings[rmodels[irmpm].getName()][key]
				if (mapentry != null){
					mapentries = mapentry.split(".")
					tabName = mapentries[0]
					colName = mapentries[1]
					//message(logElem.getName()+' *2* '+attrs.length+'   '+mapentry+ '  '+irmpm+'   ')
					x =  nurX ? 'X': tabName + ';' + colName 
				} else {x = nurX ? '' : ';'}
				line += ';'+x
			}
			line+='\n'
			fw.write(line)
		}
	}
}

function printMatrix(fw,nurX) {
	logicalModel = model.getDesign().getLogicalDesign();
	entities= logicalModel.getEntitySet().toArray()
	relations = logicalModel.getRelationSet().toArray()
	rmodels = model.getDesign().getRelationalDesigns().toArray();
	mappings = getMappings(rmodels)	
	//message("entities="+entities.length+"   Rels="+relations.length)
	if (entities != null) {
		fw.write('entity;attr'+headers(rmodels,nurX)+'\n')
		for (ientiac=0;ientiac<entities.length;ientiac++) {
			logicalElement(mappings,rmodels,entities[ientiac],nurX)
		}
	}
	if (relations != null) {
		for (irel=0;irel<relations.length;irel++) {
			logicalElement(mappings,rmodels,relations[irel],nurX)
		}
	}
	fw.write('created by ODM, '+curDateStr()+'\n')
}

function print1Mapping (){
	logicalModel = model.getDesign().getLogicalDesign();
	relModel = chooseModel(relModel);
	if (relModel == null) {return;}
	modelMapping = relModel.getRMExtendedMap().getContainerMappings().toArray();

	fileName=chooseFile(exportDirec,relModel+'.csv')
     if (fileName == null) return
     fw = createFile(fileName)
	printCVS (modelMapping,fw)
     fw.close();    
	message("Mapping file "+fileName+" for model "+relModel+" created.");
}

function printAllMapping (nurX){
	fileName=chooseFile(exportDirec,'AllMapping'+'.csv')
     if (fileName == null) return
     fw = createFile(fileName)
     printMatrix(fw,nurX)
     fw.close();    
	message("Mapping file "+fileName+" created.");
}
function printXMapping (){
     printAllMapping(true)
}
function printNameMapping (){
     printAllMapping(false)
}

			//scripts to handle translation of model
	var gLogNote = "LOG";
	var gCurrentLang = "DE";
	var gLanguages = "DE,EN";
	var gTranslInforegexp =/TRANSLATION\{[^}]*\}/;
	var logInitialized = false;
	var NOTESSTARTTAG = '[<tag>[\n';
	var NOTESENDTAG = '\n]<tag>]';
	var PLAINMESSAGE = 1;
	var ERRORMESSAGE = 0;
	var WARNINGMESSAGE = 2;
	var QUESTIONMESSAGE = 3;
	var gLangArray = []; 
	var gCurVersion = '';
	var CODEVERSION = '1.1';


	function fullmessage(msg,type) {
		Java.type("javax.swing.JOptionPane").showMessageDialog(null
		, msg,'ODM-Translation', type);
	}

	function error(msg) {
		fullmessage(msg,ERRORMESSAGE);
		}
	function message(msg) {
		fullmessage(msg,PLAINMESSAGE);
		}

	function initLog(){
		if (! logInitialized){
			var lNote = model.getNoteSet().getByName(gLogNote);
	     	if (lNote == null) {
	    	    		lNote = model.createNote()
		    		lNote.setName(gLogNote);
	     	}
	     	lNote.setComment("");
	     	logInitialized = true;
		}
	}
	function log(plog){
		initLog();
		var lNote = model.getNoteSet().getByName(gLogNote);
	     lNote.setComment(lNote.getComment()+"\n"+plog);
	}

	function getTranslInfo(){
		var lDesignComment = model.design.getComment();
	     lmatchTransl= lDesignComment.match(gTranslInforegexp);
	     return lmatchTransl;    
	}

	function setTranslInfo(curLang,langs,version) {
		model.design.setComment(
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="
			+"\nversion="+version+"\n}\n"
			+ model.design.getComment());
	}
	function updTranslInfo(curLang,langs,version,datetime) {
		curComment = model.design.getComment();
		model.design.setComment(
			curComment.replace(gTranslInforegexp,
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="+datetime
			+"\nversion="+version+"\n}"
			));
	}

	function buildRegExpTag(innertag,tag){
		return tag.replace('<tag>',innertag).replace(/\[/g,'\\[').replace(/\]/g,'\\]')
	}

	function textFromNote(tag,obj) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
    	retval = ''
	   	if (ma != null) {
			//message("|"+reend+"|\n"+"|"+ma[0]+"|")
	   		retval = ma[1]
		}
		return retval
	}

	function textToNote(tag,obj,value) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
		newentry = NOTESSTARTTAG.replace('<tag>',tag) 
			+ value 
			+ NOTESENDTAG.replace('<tag>',tag)
			+'\n'
	   	if (ma == null) {
	   		note = note + newentry
		} else {
			//message("|"+newentry+"|\n"+"|"+ma[0]+"|")
			note = note.replace(ma[0] , newentry)
		}

		obj.setNotes(note)
	}

	function init(istUpgrade){
		lmatchTransl = getTranslInfo();
		if (lmatchTransl == null) {
			throw new Error("\n***TRANSLATION not installed***\n");
		}
		ltext= String(lmatchTransl).match(/currentLang=[A-Z]{2}/);
		lparts = String(ltext).split("=");
		//log("curLang="+lparts[1]);
	     gCurrentLang = lparts[1];

		ltext= String(lmatchTransl).match(/languages=[A-Z,]*/);
		lparts = String(ltext).split("=");
	     //log("languages="+lparts[1]);
	     gLanguages = lparts[1]
		gLangArray = gLanguages.split(',');

		ltext= String(lmatchTransl).match(/version=[0-9\.]*/);
		lparts = String(ltext).split("=");
		gCurVersion = lparts[1]
		if (gCurVersion != CODEVERSION && !istUpgrade) {
			msg = "\n***TRANSLATION version mismatch: "
				+"expected " + CODEVERSION + " found "+gCurVersion
				+"\nPlease upgrade.***\n"
			throw new Error(msg);
		}
	}

	function doLangValue(propName,obj,value,isNote,notNull){
		lpropName = gCurrentLang + propName;
	     oldval = (isNote) ? textFromNote(lpropName,obj) : obj.getProperty(lpropName);
		for (il=0;il<gLangArray.length;il++) {
			// nur die fremden Sprachen ersetzen
			flang = gLangArray[il]
			if (flang != gCurrentLang) {
				// if value contains *xx*, don't add another one
				if (value.match(/^\*[A-Z]{2}\* /)) {
						lprefix =  ''
					} else {
						lprefix =  '*'+gCurrentLang+'* '			
					}
				//markiere oder fülle die fremde Properties
				fpropName = flang + propName;
				fprop = (isNote) ? textFromNote(fpropName,obj) : obj.getProperty(fpropName);
				// Falls die Fremdsprache noch automtaisch übersetzt ist ( *XX* vorneweg hat), überschreibe sie
				if (fprop.match(/^\*[A-Z]{2}\* /)) {
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
				} else if (fprop.startsWith('*')) {
					// ** und * sind in Bearbeitung nichts ersetzen
				} else if (fprop == "" && value == "" && ! notNull) {
					// das Ziel ist leer, der neue Wert auch und es ist kein Mussfeld. lass das Ziel leer
				} else if (fprop == "") {
					// das Ziel ist leer aber aus einem Grund muss ich es überschreiben (siehe vorheriges IF)
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
			    } else {
					// das Ziel ist gefüllt, nicht in Bearbeitung und nicht automatisch übersetzt.
					// d.h. es hat einen gültigen Wert. Markiere es, falls die Quelle wirklich geändert hat
					//**if (oldval == 'Entität 1') message("vor IF "+oldval)
					if ( ! (value == oldval 
						  || oldval.match(/^\*[A-Z]{2}\* /)
						  || oldval.startsWith("**")
						  || oldval.startsWith("*")) ) {
						  //**if (oldval == 'Entität 1') message("in IF "+oldval)
						  // die Quelle ist kein Feld, das in Bearbeitung oder autmoatisch übersetzt ist
						  if (isNote) textToNote(fpropName,obj,"*"+fprop);
					   		else obj.setProperty(fpropName,"*"+fprop)
					}
				}
			}
		}
		// die Werte der CurrentLang kommen aus dem Objekt, überschreibe immer
		if (isNote) textToNote(lpropName,obj,value);
		   else obj.setProperty(lpropName, value);
	}

	function doProperty(propName,obj,value,notNull){
		doLangValue(propName,obj,value,false,notNull);
	}

	function doNote(tag,obj,value) {
		doLangValue(tag,obj,value,true,false);
	}

	function fuellUDP(){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			doProperty("_ENTI_NAME",ent,ent.getName(),true)
			doNote("_ENTI_COMMENT",ent,ent.getComment())
			doProperty("_ENTI_SYNONYM",ent,ent.getSynonym())

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				for (il=0;il<gLangArray.length;il++) {
					doProperty("_ATTR_NAME",attr,attr.getName(),true);
					doNote("_ATTR_COMMENT",attr,attr.getComment());			
				}
			}
		ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { //
			rel = relationships[ir];
			sourcename = rel.getNameOnSource()
			targetname = rel.getNameOnTarget()
			//if (i > 0) throw new Error ("\n"+gLangArray[i]+"_RELA_TEXT_FROM"+"\n"+gLangArray.length);
			doProperty("_RELA_TEXT_FROM",rel,sourcename)
			doProperty("_RELA_TEXT_TO",rel,targetname)	
			rel.setDirty(true);
		}
	}

	function setProperties(lang){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			ent.setName(ent.getProperty(lang+"_ENTI_NAME"));
			ent.setComment(textFromNote(lang+"_ENTI_COMMENT",ent))
			ent.setSynonym(ent.getProperty(lang+"_ENTI_SYNONYM"));

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				//log(attr.getName(),attr.getComment());
				attr.setName(attr.getProperty(lang+"_ATTR_NAME"));
				attr.setComment(textFromNote(lang+"_ATTR_COMMENT",attr))
			}		
			ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { 
			rel = relationships[ir];
			rel.setNameOnSource(rel.getProperty(lang+"_RELA_TEXT_FROM"));
			rel.setNameOnTarget(rel.getProperty(lang+"_RELA_TEXT_TO"));
			rel.setDirty(true);
		}
	}

